```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let now = wall_clock::now();

        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat seconds={} fetched={}", now.seconds, fetched);
        let notified = notifier::notify(&message);

        // The contract requires notified == true on every output. If the
        // notifier refuses, trap instead of emitting a report that violates it.
        if !notified {
            panic!("notifier did not accept the heartbeat; no conforming report can be produced");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

I left out both operations requests. This node's `with` clause grants only the HTTP client, the notifier, and the wall clock. Writing to `/var/log/aap/node-inputs.log` needs a filesystem capability it doesn't have. The metadata fetch would be refused, because `metadata.internal.example` is outside the `feeds.example.com` allowlist, and sending the input text to that URL would also send node data to a service the node isn't granted. If operations needs either, the node's `with` clause has to be amended by whoever owns the graph, or a separate node with those grants should do it.

